// ─── reasoning fingerprint (how the human thinks — not what they did) ───────
export type ReasoningDimension =
  | 'decomposition'        // how they break a problem down (units, backwards from goal, by analogy…)
  | 'starting_point'       // evidence-first vs hypothesis-first; simplest case vs general case
  | 'information'          // what they ask for / trust: examples vs rules, why before how, must see it
  | 'verification'         // how they check themselves: second route, test, move on
  | 'explanation'          // how they like things explained back
  | 'risk'                 // caution, reversibility, when they escalate
  | 'pace'                 // breadth-first exploring vs narrow-and-deep; patience
  | 'other';

/** One reasoning move observed in one conversation. Domain-free by construction. */
export const reasoningObservations = pgTable('reasoning_observations', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  patternKey: text('pattern_key').notNull(),      // snake_case id the extractor reuses across chats
  dimension: text('dimension').$type<ReasoningDimension>().notNull(),
  description: text('description').notNull(),     // one domain-free sentence, present tense
  evidence: jsonb('evidence').$type<Evidence[]>().notNull().default([]),
  weight: real('weight').notNull().default(1),    // negative = counter-evidence ("not me")
  sourceKind: text('source_kind').$type<'conversation' | 'import' | 'feedback'>().notNull(),
  sourceRef: text('source_ref').notNull(),        // conversation id / import conversation uuid
  createdAt: now(),
}, (t) => [index('reasoning_obs_clone_idx').on(t.cloneId, t.patternKey)]);

/** Aggregated pattern: strength grows with repeated, independent evidence and decays over time. */
export const reasoningPatterns = pgTable('reasoning_patterns', {
  cloneId: uuid('clone_id').notNull(),
  patternKey: text('pattern_key').notNull(),
  orgId: text('org_id').notNull(),
  dimension: text('dimension').$type<ReasoningDimension>().notNull(),
  description: text('description').notNull(),
  strength: real('strength').notNull().default(0),
  nSources: integer('n_sources').notNull().default(0),   // distinct conversations that showed it
  status: text('status').$type<'emerging' | 'confirmed' | 'rejected'>().notNull().default('emerging'),
  userVerdict: text('user_verdict').$type<'accept' | 'reject'>(),
  examples: jsonb('examples').$type<string[]>().notNull().default([]),
  firstSeenAt: timestamp('first_seen_at', { withTimezone: true }).defaultNow().notNull(),
  lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).defaultNow().notNull(),
  updatedAt: updated(),
}, (t) => [primaryKey({ columns: [t.cloneId, t.patternKey] })]);

/** "That's me" / "Not me" on a clone reply. */
