// ─── Claude Code ingestion ──────────────────────────────────────────────────
/** Personal tokens used by the Claude Code SessionEnd hook to post transcripts. Stored hashed. */
export const ingestTokens = pgTable('ingest_tokens', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  userId: text('user_id').notNull(),
  name: text('name').notNull().default('Claude Code'),
  tokenHash: text('token_hash').notNull().unique(),
  lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
  revokedAt: timestamp('revoked_at', { withTimezone: true }),
  createdAt: now(),
});

/** One row per Claude Code session we have learned from (dedupe + resume). */
export const claudeCodeSessions = pgTable('claude_code_sessions', {
  cloneId: uuid('clone_id').notNull(),
  sessionId: text('session_id').notNull(),
  orgId: text('org_id').notNull(),
  source: text('source').$type<'local' | 'hook' | 'upload'>().notNull(),
  project: text('project'),
  bytes: integer('bytes').notNull().default(0),
  humanTurns: integer('human_turns').notNull().default(0),
  observations: integer('observations').notNull().default(0),
  status: text('status').$type<'queued' | 'done' | 'skipped' | 'failed'>().notNull().default('queued'),
  note: text('note'),
  extractedAt: timestamp('extracted_at', { withTimezone: true }),
  createdAt: now(),
}, (t) => [primaryKey({ columns: [t.cloneId, t.sessionId] })]);

// ─── self-tests ("does it sound like me?") ──────────────────────────────────
export const selfTests = pgTable('self_tests', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  batchId: uuid('batch_id').notNull(),
  domain: text('domain').notNull().default(''),
  question: text('question').notNull(),
  answer: text('answer').notNull(),
  model: text('model'),
  verdict: text('verdict').$type<'me' | 'not_me'>(),
  comment: text('comment'),
  ratedAt: timestamp('rated_at', { withTimezone: true }),
  createdAt: now(),
}, (t) => [index('self_tests_clone_idx').on(t.cloneId, t.createdAt)]);

// ─── personality (self-reported MBTI-style lens) ────────────────────────────
export const personalityTests = pgTable('personality_tests', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  answers: jsonb('answers').$type<Record<string, number>>().notNull(),
  scores: jsonb('scores').$type<Record<'EI' | 'SN' | 'TF' | 'JP', number>>().notNull(),
  type: text('type').notNull(),
  createdAt: now(),
}, (t) => [index('personality_clone_idx').on(t.cloneId, t.createdAt)]);

// auth abuse tracking — per-account lockout (defeats distributed password spray that IP limits miss)
export const authFailures = pgTable('auth_failures', {
  id: uuid('id').primaryKey().defaultRandom(),
  email: text('email').notNull(),
  createdAt: now(),
}, (t) => [index('auth_failures_email_idx').on(t.email, t.createdAt)]);
